--- MODULE: Config-Key and Menu-Command Constants
--- DESCRIPTION:
--- One constant per configuration key, leaf and menu command id. A misspelt
--- string key reads as nil and the default silently applies; a misspelt
--- constant fails at the first access, because every table below refuses a
--- name it does not hold.
--- ==============================================================================

local M = {}

--- Seals one table so an unknown name raises instead of answering nil.
--- @param label string The table name, quoted in the error.
--- @param values table The constants.
--- @return table values, sealed.
local function strict(label, values)
	return setmetatable(values, {
		__index = function(_, name)
			error("config_keys." .. label .. " has no constant " .. tostring(name), 2)
		end,
		__newindex = function(_, name)
			error("config_keys." .. label .. " is read-only (" .. tostring(name) .. ")", 2)
		end,
	})
end

